<?php
$mode=$_SERVER['REQUEST_METHOD']==='POST'?(val('schedule_mode')?:'now'):(($item['status']??'')==='draft'?'draft':($schedule['mode']??'now'));
function schedule_value(string $key,string $fallback=''): string {global $schedule;return $_SERVER['REQUEST_METHOD']==='POST'?val($key):(string)($schedule[$key]??$fallback);}
$selectedDays=$_SERVER['REQUEST_METHOD']==='POST'?(is_array($_POST['weekdays']??null)?$_POST['weekdays']:[]):[];
if($_SERVER['REQUEST_METHOD']!=='POST'&&$schedule)for($i=1;$i<=7;$i++)if((int)$schedule['weekday_mask']&(1<<($i-1)))$selectedDays[]=(string)$i;
?>
<section class="availability-editor"><h2><?=e(t('Availability'))?></h2><p class="hint"><?=e(t('Upload once and choose when customers can order. All dates and times use'))?> <?=e(cfg('timezone'))?>.</p><div class="field"><label for="schedule_mode"><?=e(t('When should this dish go live?'))?></label><select id="schedule_mode" name="schedule_mode"><option value="now" <?=$mode==='now'?'selected':''?>><?=e(t('Available now'))?></option><option value="once" <?=$mode==='once'?'selected':''?>><?=e(t('Schedule a specific date and time'))?></option><option value="weekly" <?=$mode==='weekly'?'selected':''?>><?=e(t('Repeat weekly'))?></option><option value="draft" <?=$mode==='draft'?'selected':''?>><?=e(t('Save as draft'))?></option></select></div>
<div data-schedule-section="once"><?php field('starts_at',t('Goes live at'),'datetime-local','',$_SERVER['REQUEST_METHOD']==='POST'?val('starts_at'):($schedule&&$schedule['start_at']?local_time($schedule['start_at'],'Y-m-d\TH:i'):'')); ?></div>
<div data-schedule-section="now once"><?php field('expires_at',t('Available until'),'datetime-local','',$_SERVER['REQUEST_METHOD']==='POST'?val('expires_at'):($schedule&&$schedule['end_at']?local_time($schedule['end_at'],'Y-m-d\TH:i'):($editing&&$item['expires_at']<'9999-01-01'?local_time($item['expires_at'],'Y-m-d\TH:i'):''))); ?></div>
<div data-schedule-section="weekly"><fieldset class="weekday-picker"><legend><?=e(t('Choose weekdays'))?></legend><?php foreach([1=>t('Mon'),2=>t('Tue'),3=>t('Wed'),4=>t('Thu'),5=>t('Fri'),6=>t('Sat'),7=>t('Sun')] as $number=>$day): ?><label><input type="checkbox" name="weekdays[]" value="<?=$number?>" <?=in_array((string)$number,$selectedDays,true)?'checked':''?>><span><?=e($day)?></span></label><?php endforeach ?></fieldset><div class="form-grid"><?php field('start_time',t('Goes live at'),'time','',schedule_value('start_time'));field('end_time',t('Stops taking orders at'),'time','',schedule_value('end_time'));field('start_date',t('First available date'),'date','',schedule_value('start_date',(new DateTimeImmutable('today',new DateTimeZone(cfg('timezone'))))->format('Y-m-d')));field('end_date',t('Final date (optional)'),'date','',schedule_value('end_date')); ?></div><p class="hint"><?=e(t('An end time earlier than the start time means the next morning. Example: Friday 8 PM–2 AM runs into Saturday. Reviews stay attached to this same dish each week.'))?></p></div><div data-schedule-section="draft"><p class="alert"><?=e(t('Drafts are saved to your menu and are not shown to customers.'))?></p></div></section>
